import { test, expect } from '@playwright/test';

test.describe('Splash — экран входа', () => {
  test('SP-02 На splash ровно один заголовок верхнего уровня #6a98690c @prod-safe', async ({ page }) => {
    // 1. Открыть `/`.
    await page.goto('/');
    await expect(page.getByRole('button', { name: 'בואו נתחיל' })).toBeVisible();

    // 2. Собрать `h1`/`h2`/`[role=heading]` с `aria-level`.
    const top = page.getByRole('heading', { level: 1 });
    await expect(top).toHaveCount(1);
    await expect(top).toHaveText('ברוכים הבאים לאור הגאולה');
    // Wordmark «אור הגאולה» — не заголовок верхнего уровня.
    await expect(page.getByRole('heading', { level: 1, name: 'אור הגאולה', exact: true })).toHaveCount(0);
    await expect(page.getByRole('heading', { level: 2, name: 'אור הגאולה', exact: true })).toHaveCount(0);
  });
});
